// Original, deterministic teaching traces. Numbers are explicit scenario assumptions,
// not benchmark claims. Section examples are intentionally identified as shared cases.
const step = (title, explanation, why, states, path, result) => ({ title, explanation, why, states, path, result });
const study = (title, concept, scenario, actors, steps, tradeoff, question, answer) => ({ title, concept, scenario, actors, steps, tradeoff, question, answer });

export const systemDesignWalkthroughs = {
  'messaging-and-streaming': study(
    'Recover a partitioned consumer after a crash',
    'A retained event log stores ordered records within each partition. Consumers track their position with offsets, so recovery can replay records independently of when producers wrote them.',
    'Partition P0 contains offsets 40, 41, and 42. In this example a committed offset means the next record to read. One consumer owns P0 in its group.',
    ['Producer', 'Partition P0', 'Consumer', 'Result store'], [
      step('Append ordered records', 'The producer appends three events to P0. Their offsets establish an order inside this partition, not a global order across all partitions.', 'Choose partition keys around the ordering requirement. Related events placed in different partitions can be processed independently.', ['Append events', 'Offsets 40, 41, 42', 'Next offset: 40', 'No results'], [0, 1], 'The consumer has an ordered sequence to read.'),
      step('Process and checkpoint', 'The consumer handles record 40, durably saves its result, and commits next offset 41.', 'A checkpoint tells recovery where to resume. Committing before saving the result risks skipping unfinished work.', ['Append complete', 'Records retained', 'Next offset: 41', 'Result 40 saved'], [2, 3], 'Record 40 is complete and checkpointed.'),
      step('Crash before the next checkpoint', 'The consumer saves the result of record 41, then crashes before committing offset 42. Its durable checkpoint remains 41.', 'The output and checkpoint are separate writes unless a supported transaction explicitly coordinates them.', ['No new event', '41 available to replay', 'Crashed; checkpoint 41', 'Result 41 saved'], [2, 3], 'Recovery will revisit work that already produced an effect.'),
      step('Resume without duplicating effects', 'The replacement owner resumes at 41, recognizes the saved event identity, skips the duplicate effect, and commits next offset 42.', 'Retention permits replay; it does not automatically make downstream operations idempotent.', ['Producer independent', 'Next record: 42', 'Checkpoint: 42', 'One result per event'], [1, 2], 'Replaying a record can safely recover interrupted processing.'),
    ], 'Logs support replay and independent consumers, but retention, partition skew, ordering, and replay-safe effects require explicit design.',
    'Does adding consumers beyond the partition count always improve throughput?', 'No. Under exclusive partition ownership within a consumer group, extra consumers have no partition to read. More partitions may help parallelism but change ordering and operational costs.'),
  'replication-and-consistency': study(
    'Keep a user’s reads from going backward',
    'Session guarantees describe the consistency one client observes across requests. Monotonic reads prevent a session from observing an older version after it has already seen a newer one.',
    'Replica A has profile version 12 and replica B has version 10. Assume versions are ordered and the router can enforce a minimum version for this session.',
    ['User session', 'Read router', 'Replica A', 'Replica B'], [
      step('Read the newer version', 'The first request reaches A and returns profile version 12. The session records 12 as its minimum observed version.', 'The minimum is evidence of what this user has seen. A later response should not silently take the same session backward.', ['Observed v12', 'Minimum version: 12', 'Version 12', 'Version 10'], [2, 0], 'The session now carries a freshness requirement.'),
      step('Try a different replica', 'The next request is considered for B. B only has version 10, so it cannot yet satisfy the session’s minimum.', 'Blind round-robin routing can produce a time-travel effect even if each replica eventually catches up.', ['Requires at least v12', 'Check replica progress', 'Version 12', 'Version 10: too old'], [1, 3], 'The router must not return B’s older version.'),
      step('Choose a valid response path', 'Route to A, wait for B to catch up within a deadline, or fail honestly if no suitable replica is reachable.', 'A minimum-version rule makes a consistency promise explicit, including what happens when it cannot be met.', ['Receives v12', 'Route to A', 'Returns version 12', 'Still behind'], [1, 2], 'This session avoids an older read.'),
      step('Allow the replica to catch up', 'B applies the missing updates and reaches version 12. It can now satisfy this session’s minimum version.', 'This guarantee is scoped to the session and versioned data. It is not a blanket promise of globally linearizable reads.', ['Minimum remains v12', 'A or B eligible', 'Version 12', 'Version 12'], [2, 3], 'Routing flexibility returns as replication progresses.'),
    ], 'Version-aware routing improves session consistency but can increase latency or reduce availability when suitable replicas are unreachable.',
    'Is always sending a user to the same replica sufficient forever?', 'It helps while that replica stays available and does not regress, but failover needs a policy for preserving the session guarantee. A minimum-version requirement makes that policy explicit.'),
  'resilience-patterns': study(
    'Fit retries inside one deadline',
    'A timeout limits an individual wait; a deadline limits the whole operation. Retries need to fit inside the remaining budget and should use backoff and jitter to avoid synchronized overload.',
    'A request has a 1,000 ms total budget. Assume the first dependency attempt uses 300 ms, the chosen backoff is 100 ms, and 100 ms is reserved to finish the response.',
    ['Caller', 'Service', 'Dependency', 'Deadline budget'], [
      step('Start with a total budget', 'The service receives a request and establishes a deadline 1,000 ms away. It propagates the remaining budget to downstream work.', 'Giving every nested call a fresh one-second timeout can make an end-to-end operation take far longer than one second.', ['Waiting', 'Deadline established', 'Not called', '1,000 ms left'], [0, 1], 'All attempts share one finite budget.'),
      step('Spend time on an attempt', 'The first attempt times out after 300 ms. The remaining budget is approximately 700 ms before other overhead.', 'A timeout does not prove that a remote write failed. Retry only when the operation is safe or protected by a stable idempotency key.', ['Still waiting', 'Attempt 1 timed out', 'Outcome may be unknown', '700 ms left'], [1, 2], 'A retry must fit the remaining time and correctness policy.'),
      step('Back off before retrying', 'Wait the chosen 100 ms backoff, leaving about 600 ms. Reserve 100 ms for response work, so the next attempt gets at most 500 ms.', 'Jitter varies delays across callers; it prevents all failed requests from hammering the dependency again at the same instant.', ['Still waiting', 'Backoff: 100 ms', 'No call during delay', '600 ms left'], [1, 3], 'The second attempt has a bounded 500 ms allowance.'),
      step('Stop when the budget is exhausted', 'If the second attempt also uses 500 ms without success, stop retrying and return the documented failure or unresolved outcome within the remaining response budget.', 'Retries must have a stopping rule. Cancellation should be propagated when possible, but it does not guarantee a remote side effect was undone.', ['Receives honest outcome', 'No third attempt', 'Cancel if supported', '100 ms to finish'], [1, 0], 'The caller’s deadline remains the controlling limit.'),
    ], 'Retries can hide short failures but multiply dependency traffic. Budget them at the appropriate layer and limit total concurrent attempts.',
    'If three nested layers each try three times, how many deepest calls are possible?', 'Up to 3 × 3 × 3 = 27 attempts for one original request. Coordinate retry ownership and enforce an end-to-end deadline to avoid this amplification.'),
  'common-building-blocks': study(
    'Build a feed without doing all the work on every read',
    'Fan-out on write prepares per-reader feed entries when a post is created. Fan-out on read gathers candidate posts when a reader opens the feed. Their cost depends on audience size and read frequency.',
    'An author has 1,000 followers and creates post P7. Assume feed entries contain post IDs rather than full copies of the post body.',
    ['Author', 'Post store', 'Fan-out worker', 'Follower feeds'], [
      step('Store the post once', 'Create P7 in the authoritative post store and durably schedule fan-out work. The post can exist while feed delivery is still pending.', 'Writing the post and publishing a task have a crash window unless coordinated through an outbox or another reliable mechanism.', ['Publish P7', 'P7 durable', 'Task pending', 'No P7 entries yet'], [0, 1], 'The content has one authoritative record.'),
      step('Prepare follower entries', 'The worker adds a reference to P7 to eligible followers’ feeds, using a unique follower-and-post pair to tolerate repeated jobs.', 'The work scales with audience size: this example needs up to 1,000 feed insertions for one post.', ['Post published', 'Body stored once', 'Fan out to 1,000', 'P7 IDs inserted'], [2, 3], 'Reads can reuse prepared candidate lists.'),
      step('Read a prepared feed', 'A follower loads recent feed IDs, fetches the corresponding visible posts, and applies authorization and deletion checks before returning content.', 'A cached feed entry must not bypass privacy rules. Visibility can change after fan-out.', ['Follower opens feed', 'Verify visible posts', 'May still be processing', 'Read prepared IDs'], [3, 1], 'The read path avoids scanning every followed author.'),
      step('Handle a very large audience', 'For an author with millions of followers, consider merging recent posts at read time instead of inserting into every feed immediately.', 'A hybrid policy trades some read work for less write amplification. Choose the threshold from traffic and latency measurements.', ['Large audience author', 'Recent posts retained', 'Skip huge fan-out', 'Merge at read time'], [1, 3], 'Different author populations can use different delivery paths.'),
    ], 'Precomputed feeds improve read speed but add write amplification, delayed delivery, invalidation, and privacy checks.',
    'Does deleting the original post automatically remove every feed entry?', 'No. References may remain. Reads must enforce deletion and visibility immediately, while background cleanup can remove obsolete entries.'),
  'ai-system-building-blocks': study(
    'Answer a question with retrieved evidence',
    'Retrieval-augmented generation finds relevant material before asking a model to produce an answer. Retrieval supplies context; it does not guarantee the model’s answer is correct or that retrieved text is trustworthy.',
    'An internal assistant answers a question about an employee policy. Only documents the current user may access should be retrieved or shown.',
    ['User', 'Retriever', 'Allowed documents', 'Answer model'], [
      step('Establish the query and access scope', 'Authenticate the user, identify their document permissions, and create a retrieval query from the question.', 'Access control belongs before evidence reaches the model. A prompt asking the model to hide confidential text is not an authorization boundary.', ['Policy question', 'Query + access filter', 'Allowed scope known', 'No context yet'], [0, 1], 'The search is scoped to the user’s permissions.'),
      step('Retrieve useful passages', 'Search authorized document chunks and rank candidates. Include enough surrounding text to preserve conditions, exceptions, and dates.', 'Similarity is not truth. An old or partially relevant passage can produce a plausible but incorrect answer.', ['Waiting', 'Rank passages', 'Relevant policy chunks', 'No context yet'], [1, 2], 'The system has candidate evidence rather than a confirmed answer.'),
      step('Generate within the evidence', 'Pass the question and selected passages to the model with instructions to distinguish supported claims from uncertainty. Treat instructions embedded in documents as untrusted data.', 'Retrieved content can contain prompt injection. Keep tool permissions and sensitive operations outside the authority of that text.', ['Waiting', 'Context assembled', 'Text treated as data', 'Draft supported answer'], [2, 3], 'The model drafts an answer from bounded context.'),
      step('Evaluate and respond honestly', 'Check the response against the supplied evidence and access policy. If support is missing or contradictory, ask for clarification or state that the answer is not established.', 'Fluent language is not a correctness test. Evaluate retrieval quality and answer faithfulness separately using representative questions.', ['Answer or uncertainty', 'Retrieval measured', 'Evidence checked', 'Response reviewed'], [3, 0], 'The user gets an answer with an honest uncertainty boundary.'),
    ], 'Retrieval can improve relevance and freshness but adds indexing, permission filtering, latency, and evaluation work.',
    'Can two users safely share a cached answer solely because their questions are similar?', 'Not necessarily. Cache keys and reuse policies must include relevant permission scope, document versions, and other context so a cached answer cannot leak restricted information.'),
  welcome: study(
    'Grow a tiny link shortener',
    'System design connects a user need to a set of components and explains what each component costs. Begin with one working request, measure its limits, and add complexity only when a requirement demands it.',
    'You are building short links for a college event. Assume 100 link creations and 10,000 redirects per day. Links must keep working after a server restart.',
    ['Visitor', 'Application', 'Database', 'Cache'], [
      step('Save the first link', 'The visitor sends a long URL. The application creates a unique short code and stores the code-to-URL mapping in a durable database before returning success.', 'Application memory disappears on restart. The database owns the mapping; a unique constraint catches code collisions so the application can retry.', ['Create /abc', 'Validate + create code', 'abc = event URL', 'Empty'], [1, 2], 'A short code now has a durable destination.'),
      step('Follow the short link', 'A visitor requests /abc. The application looks up abc and responds with an HTTP redirect. The browser then makes a separate request to the destination website.', 'The shortener returns a destination address; it does not normally fetch and relay the entire destination page.', ['Open /abc', 'Return redirect', 'Read abc', 'Empty'], [2, 1], 'One redirect initially requires one database lookup.'),
      step('Estimate before scaling', '10,000 redirects / 86,400 seconds is about 0.12 requests per second on average. A 100-fold event spike is about 12 requests per second. Measure whether the simple design meets that peak.', 'A large daily number can still be a small per-second workload. Average traffic also hides bursts, so state both assumptions.', ['Peak: 12 requests/s', 'Measure latency', 'Measure read load', 'Not yet needed'], [0, 1], 'There is no evidence yet that a distributed cache is necessary.'),
      step('Respond to measured growth', 'Later, assume 1,000 redirects per second and a measured 90% cache hit rate. The app checks cached mappings first; roughly 100 reads per second still reach the database.', 'The cache reduces repeated reads but introduces expiry and invalidation. Deleted or edited links must stop using old cached destinations.', ['1,000 requests/s', 'Check cache first', '100 reads/s', '900 hits/s'], [1, 3], '1,000 × (1 − 0.90) = 100 database reads/s.'),
    ], 'Caching trades freshness and operational simplicity for lower read load. Keep the database as the source of truth and test the cache-miss path.',
    'If the cache disappears, what happens to the database load?', 'All 1,000 requests per second may reach it: ten times the warm-cache load. Use bounded concurrency, rate limits, and a tested fallback instead of assuming the database can absorb it.'),
  'introduction-to-system-design': study(
    'Turn “build a ticket site” into a design',
    'A functional requirement describes an action, such as reserving a seat. A non-functional requirement describes a measurable property, such as response time or availability. Constraints decide which architecture is appropriate.',
    'A venue has 500 seats. Assume 2,000 people arrive together and each seat may have only one successful reservation.',
    ['Buyer', 'Booking API', 'Seat database', 'Email worker'], [
      step('Define success precisely', 'Write the central rule first: at most one active reservation per seat. Separately set a target that 95% of reservation responses finish within 500 ms under the expected peak.', '“Fast and scalable” cannot be tested. A correctness rule and a latency target let you evaluate competing designs.', ['Choose seat A7', 'Target: p95 < 500 ms', '500 seats', 'No message'], [0, 1], 'Correctness and speed are separate acceptance criteria.'),
      step('Protect the shared state', 'Two buyers may request A7 together. Use an atomic conditional update or a transaction with the appropriate constraint so only the available seat can become reserved.', 'Checking availability and writing later without coordination allows both buyers to observe an available seat.', ['Request A7', 'Reserve if available', 'A7 reserved once', 'No message'], [1, 2], 'The database decides the winner of the race.'),
      step('Move optional work off the path', 'Commit the reservation and a notification record together. A background worker sends confirmation email after the reservation is durable.', 'Email latency should not keep the seat transaction open. The notification record prevents a crash between commit and publish from silently losing the email task.', ['Reservation confirmed', 'Return reservation ID', 'Reservation + outbox', 'Send later'], [2, 3], 'Booking success and email delivery have different lifecycles.'),
      step('Test the failure case', 'Stop the email worker and submit more reservations. Bookings should remain correct while notification tasks accumulate. Restart the worker and process the backlog safely.', 'A useful design explains what degrades, how it is detected, and how the system recovers—not only the happy path.', ['Can still reserve', 'Accept bookings', 'Pending notifications', 'Recover + deduplicate'], [2, 3], 'Worker downtime delays emails without duplicating seat ownership.'),
    ], 'Moving work to a queue shortens the response path but creates delayed completion, retries, and monitoring work.',
    'Would adding five API servers prevent double booking?', 'No. More servers can create more concurrent attempts. Correctness needs coordination at the shared seat record, regardless of how many API servers exist.'),
  'core-concepts': study(
    'Size a service for a traffic spike',
    'Scalability is the ability to handle growing work while meeting an objective. Throughput counts completed work per unit time; latency measures how long one request takes. Capacity estimates are hypotheses to validate under load.',
    'Assume 1 million daily users, 10 requests per user per day, and a peak-to-average factor of 5. A load test shows one server sustains 300 requests/s at the required latency.',
    ['Users', 'Traffic estimate', 'Server pool', 'Shared database'], [
      step('Find average demand', 'Multiply users by requests: 1,000,000 × 10 = 10 million requests per day. Divide by 86,400 seconds: about 116 requests per second.', 'Users are not requests per second. Include how often users act and the time period in every estimate.', ['1M daily users', '10M requests/day', 'Not sized', 'Not measured'], [0, 1], 'Average demand ≈ 116 requests/s.'),
      step('Account for peak traffic', 'Apply the assumed 5× peak: 116 × 5 ≈ 580 requests per second. Use observed event traffic to replace this multiplier when real measurements exist.', 'A system sized only for the average builds a queue during busy periods, increasing response time even before it starts returning errors.', ['Busy period', 'Peak ≈ 580/s', '300/s per server', 'Measure peak reads'], [1, 2], 'ceil(580 / 300) = 2 servers for nominal peak capacity.'),
      step('Budget for a failure', 'With two servers, losing one leaves only 300 requests/s of capacity. Three servers leave 600 requests/s after one failure, just above the assumed peak.', 'Failover is useful only if the remaining machines can accept the work. This is a minimum estimate; latency variability may require more headroom.', ['Peak ≈ 580/s', 'One server unavailable', '2 × 300 = 600/s', 'Still shared'], [1, 2], 'Three servers meet this simplified one-server-failure budget.'),
      step('Check the next bottleneck', 'If every request performs two database reads, peak demand is approximately 1,160 reads/s. Load-test the database too; adding API servers does not increase its capacity.', 'End-to-end capacity is constrained by shared dependencies. Watch tail latency and saturation, not just average CPU.', ['Wait for response', 'Observe p95 + p99', 'API capacity checked', '1,160 reads/s'], [2, 3], 'The estimate becomes a test plan for both tiers.'),
    ], 'Extra capacity costs money, while running close to saturation raises queueing delay and leaves little recovery margin.',
    'If the peak multiplier rises from 5 to 10, how many servers cover one failure?', 'Peak demand becomes about 1,160 requests/s. Four surviving servers provide 1,200 requests/s, so at least five are needed under these assumptions. Shared dependencies still need separate validation.'),
  networking: study(
    'Follow a browser request',
    'A URL names a resource, DNS helps find a server address, transport moves bytes, and HTTP describes the request and response. Separating these jobs makes network failures easier to diagnose.',
    'A browser loads https://shop.example/products/42. This example uses a fresh HTTPS connection over TCP; cached DNS and reused connections can skip work.',
    ['Browser', 'DNS resolver', 'Web server', 'Application'], [
      step('Resolve the name', 'The browser asks for the address of shop.example. A resolver answers from its cache or queries the DNS hierarchy and caches the result for its allowed lifetime.', 'The hostname is not an IP address. DNS gives an address to connect to; it does not return the product page.', ['Resolve shop.example', 'Return server IP', 'Waiting', 'Waiting'], [0, 1], 'The browser now knows a destination address.'),
      step('Establish a secure channel', 'The browser establishes TCP and negotiates TLS. It validates the server certificate and derives keys before sending the protected HTTP request.', 'Encryption protects data in transit. Certificate validation also checks that the browser reached a server authenticated for the requested hostname.', ['TCP + TLS handshake', 'Answer cached', 'Secure connection', 'Waiting'], [0, 2], 'Connection setup adds round trips before application work.'),
      step('Handle the HTTP request', 'The web server forwards GET /products/42 to the application. The application retrieves the product and constructs a response with a status, headers, and body.', 'A successful network connection does not guarantee a successful application response. HTTP 404 and 500 belong to a different diagnostic layer.', ['GET /products/42', 'Answer cached', 'Route request', 'Build product response'], [2, 3], 'The request path now includes application processing.'),
      step('Return and reuse', 'The response travels back to the browser. The browser can reuse the connection for later requests when supported and permitted by the protocol and server.', 'Connection reuse reduces repeated setup. Total latency still includes network travel, server queueing, processing, and transfer time.', ['Render product', 'Answer cached', 'Connection reusable', 'Response complete'], [2, 0], 'A slow page needs a breakdown, not a guess about “the network”.'),
    ], 'Caching DNS and reusing connections improve latency but require expiry, timeout, and connection-lifecycle handling.',
    'The name resolves, but the connection times out. Should you debug the product query first?', 'Start with reachability, routing, firewall rules, and whether the server is listening. The request may not have reached application code at all.'),
  'load-balancing': study(
    'Route requests and survive a server failure',
    'A load balancer selects a backend for each request or connection. It spreads work and removes unhealthy destinations, but it neither replicates application data nor guarantees spare capacity.',
    'Assume two healthy, stateless API servers and round-robin routing. Requests have similar cost; health checks run periodically.',
    ['Client', 'Load balancer', 'Server A', 'Server B'], [
      step('Send the first request', 'The balancer receives request 1 and chooses server A. The server handles it using shared durable storage rather than relying on local session memory.', 'Any healthy backend should be able to handle the next request. Otherwise a change of destination can lose a user’s session.', ['Request 1', 'Choose A', 'Handling request 1', 'Healthy, idle'], [1, 2], 'Request 1 is assigned to A.'),
      step('Rotate to the next server', 'Request 2 goes to B. Round robin alternates destinations; it does not measure how long a request will run.', 'Equal request counts are not necessarily equal work. Long uploads and short reads can need a more load-aware routing policy.', ['Request 2', 'Choose B', 'Healthy', 'Handling request 2'], [1, 3], 'Both servers receive traffic.'),
      step('Detect a failure', 'Server A stops responding. After the configured failure threshold, health checks remove A from the eligible pool. Requests sent before detection may still fail.', 'Failover is not instantaneous. Timeouts and safe retry rules are needed during the detection interval.', ['May see an error', 'Exclude A', 'Unhealthy', 'Healthy'], [1, 2], 'The routing pool now contains only B.'),
      step('Continue with less capacity', 'New requests go to B. Monitor its latency and queue length. If it cannot serve the entire peak, shed excess traffic or add capacity.', 'A healthy destination can still be overloaded. Redundancy must include both multiple machines and enough surviving capacity.', ['Request 3', 'Choose B', 'Excluded', 'Handling all traffic'], [1, 3], 'Availability now depends on B and the remaining infrastructure.'),
    ], 'More backends improve capacity and fault tolerance but add health checks, connection management, and coordination around shared state.',
    'Can you safely retry every failed request on B?', 'No. Reads are often safe, but a timed-out write might already have committed on A. Use idempotency keys or another deduplication mechanism for operations with side effects.'),
  'api-design': study(
    'Retry an order without creating it twice',
    'An API is a contract between independently changing programs. Besides request fields and response shapes, the contract needs validation, error semantics, and behavior when the client cannot tell whether a request succeeded.',
    'A buyer submits one order. The server commits it, but the connection drops before the response reaches the client.',
    ['Client', 'Order API', 'Order database', 'Retry'], [
      step('Identify one user intent', 'The client generates key order-attempt-7 and sends it with POST /orders. It keeps that same key for retries of this particular purchase.', 'A retry repeats an intent; a new purchase is a different intent. Generating a new key on every attempt defeats deduplication.', ['POST + key 7', 'Validate request', 'No order yet', 'Not needed'], [0, 1], 'All retries of this purchase carry the same identity.'),
      step('Commit once', 'Within a coordinated transaction, the API creates order 81 and records the idempotency key and result. Enforce uniqueness so concurrent requests cannot both win.', 'A check followed by an unprotected insert races. The deduplication record must be coordinated with the side effect it protects.', ['Waiting', 'Commit result', 'Key 7 → order 81', 'Not needed'], [1, 2], 'One durable order exists.'),
      step('Lose the response', 'The response is lost after commit. The client sees a timeout, which means the outcome is unknown—not that the server rolled back.', 'Networks can fail after the work finishes. Treating every timeout as a definite failure creates duplicate side effects.', ['Timed out', 'Order already saved', 'Key 7 → order 81', 'Reuse key 7'], [0, 3], 'The client must resolve an ambiguous outcome.'),
      step('Replay the recorded result', 'The retry carries key 7 and the same payload. The API looks up the stored result and returns order 81. A different payload with the same key should be rejected.', 'Store keys for a documented retention period and scope them to the caller. Idempotency is an API behavior, not just a header name.', ['Receives order 81', 'Return stored result', 'Still one order', 'Completed'], [2, 1], 'Two attempts produce one purchase.'),
    ], 'Idempotency requires storage, retention rules, concurrency control, and a policy for in-progress attempts.',
    'Should two intentional purchases of the same item share a key?', 'No. They are two business operations and need distinct keys. Only retries of the same intended operation reuse a key.'),
  'api-infrastructure': study(
    'Protect a small API with a token bucket',
    'A gateway centralizes cross-cutting checks such as routing and rate limits. A token bucket allows a bounded burst while limiting the long-term rate: requests consume tokens and time replenishes them.',
    'Assume a per-user bucket capacity of 3 tokens and a refill rate of 1 token per second. All shown burst requests arrive before the first refill.',
    ['Client', 'Gateway', 'Token bucket', 'API server'], [
      step('Begin with a full bucket', 'The bucket starts with 3 tokens. The gateway identifies the user before looking up that user’s quota.', 'A global quota can let one noisy caller consume everyone’s allowance. Choose the limit key according to the resource you want to protect.', ['Ready to burst', 'Identify user', '3 tokens', 'Healthy'], [1, 2], 'Burst allowance = 3 requests.'),
      step('Accept three requests', 'Each admitted request atomically consumes one token. Three arrivals reduce the bucket from 3 to 0 and are forwarded to the API.', 'The check and decrement must be coordinated; otherwise concurrent gateways can all observe the same last token.', ['3 requests accepted', 'Forward allowed work', '0 tokens', 'Processes 3 requests'], [1, 3], 'The burst budget is exhausted.'),
      step('Reject the next arrival', 'A fourth request arrives before refill. The gateway returns HTTP 429 and, where appropriate, guidance about when to retry.', 'Rejecting early avoids spending scarce database or application capacity on work that the policy will not permit.', ['Request 4: HTTP 429', 'Reject excess', '0 tokens', 'No fourth request'], [1, 0], 'The API is protected from this caller’s excess burst.'),
      step('Refill with time', 'After one second without another admission, the bucket has 1 token. The next request consumes it and proceeds. Idle time can refill only up to the capacity of 3.', 'The refill rate and bucket capacity control different things: sustainable rate and immediate burst size.', ['Next request allowed', 'Forward request', '1 → 0 tokens', 'Processes next request'], [1, 3], 'A 1 request/s refill does not mean “one request in every clock second”.'),
    ], 'Strict distributed limits require coordination; local limits are faster but may admit a larger aggregate burst across multiple gateways.',
    'After 20 idle seconds, does this bucket contain 20 tokens?', 'No. It caps at 3 tokens, so it permits a burst of at most 3 before waiting for additional refill.'),
  'api-security': study(
    'Check identity and permission separately',
    'Authentication establishes who is making a request. Authorization decides whether that identity may perform this action on this resource. A valid login alone never grants access to every record.',
    'Alice is signed in and requests invoice 92. Invoice 92 belongs to Bob. Assume the API uses signed access tokens.',
    ['Alice', 'API', 'Token verifier', 'Invoice store'], [
      step('Receive a credential', 'Alice sends a token with GET /invoices/92 over HTTPS. The API treats the token and invoice ID as untrusted input.', 'Decoding a token only reads its contents. It does not establish that the issuer signed it or that it is valid for this API.', ['Request invoice 92', 'Credential received', 'Not verified', 'Owner: Bob'], [0, 1], 'The server has a claim, not yet a trusted identity.'),
      step('Authenticate the caller', 'Validate the signature using trusted keys and allowed algorithms, then check issuer, audience, and expiry. The accepted token identifies Alice.', 'A token intended for a different service or an expired token must not be accepted simply because its signature parses.', ['Identity: Alice', 'Authenticated', 'Checks passed', 'Owner: Bob'], [1, 2], 'The API knows who is asking.'),
      step('Authorize this resource', 'Look up invoice 92 within the caller’s permitted tenant or ownership scope. Alice is not the owner and has no role granting access.', 'Checking only whether the caller is logged in exposes other users’ records when someone changes an ID in a URL.', ['No permission', 'Check ownership', 'Valid identity', 'Alice ≠ Bob'], [1, 3], 'A valid identity still fails the resource policy.'),
      step('Deny without disclosing data', 'Return the API’s chosen denial response and no invoice body. Some APIs use 404 to avoid disclosing resource existence; others use 403.', 'Apply the same policy on every server-side access path. Hiding a button in the browser is not authorization.', ['Access denied', 'No invoice body', 'Token still valid', 'Invoice unchanged'], [1, 0], 'Bob’s data remains private.'),
    ], 'Stateless tokens reduce session lookups but complicate rapid revocation. Authorization may still need current server-side data.',
    'Can the frontend’s “owner only” button replace the server check?', 'No. A client can call the endpoint directly. The API must enforce resource and tenant permissions regardless of what the interface displays.'),
  'communication-patterns': study(
    'Deliver a background job despite a crash',
    'Asynchronous communication separates acceptance from completion. A queue holds pending work so producers and consumers can run at different speeds, but the application must still handle retries and duplicate delivery.',
    'An order creates a receipt job with ID receipt-81. Assume a durable broker with publisher confirmation and manual consumer acknowledgements.',
    ['Order service', 'Queue', 'Worker', 'Receipt store'], [
      step('Publish the task', 'The producer sends receipt-81 and waits for the broker’s publisher confirmation under the configured durability policy.', 'A publisher confirmation covers acceptance by the broker. It does not mean that a worker has completed the business task.', ['Publish receipt-81', 'Ready: 1', 'Idle', 'No receipt'], [0, 1], 'One task is pending, not completed.'),
      step('Commit the effect', 'The queue delivers receipt-81. The worker writes the receipt with a unique job ID, but crashes immediately after that commit and before acknowledging delivery.', 'Business completion and broker acknowledgement are separate events. The gap between them is a common source of duplicates.', ['Publish confirmed', 'Unacknowledged: 1', 'Crashed after commit', 'receipt-81 saved'], [2, 3], 'The receipt exists while the broker still considers delivery unfinished.'),
      step('Redeliver after failure', 'The broker detects the lost consumer and makes the unacknowledged task eligible for delivery again. A replacement worker receives receipt-81.', 'At-least-once processing can repeat work. Deduplicate the business operation using a stable identifier, not the worker process identity.', ['No new order', 'Redeliver receipt-81', 'Replacement worker', 'receipt-81 exists'], [1, 2], 'The same logical task is delivered twice.'),
      step('Deduplicate and acknowledge', 'The replacement sees the durable receipt record and avoids repeating the write. It acknowledges the task, allowing the broker to remove it.', 'For external side effects such as sending email, a local record alone cannot close every crash window; use provider idempotency or a deliberate reconciliation policy.', ['Order unchanged', 'Pending: 0', 'Acknowledged', 'One stored receipt'], [2, 1], 'Duplicate delivery produces one stored receipt in this example.'),
    ], 'Queues absorb temporary bursts but do not create processing capacity. Track oldest-message age, retries, and poison messages.',
    'What if the worker acknowledges before saving the receipt?', 'A crash after acknowledgement can lose the job without its effect being completed. Acknowledge after durable handling, and make retries safe.'),
  caching: study(
    'Read, cache, update, and invalidate a product',
    'A cache stores a reusable copy of data. In cache-aside, application code checks the cache, loads missing data from the source, and fills the cache. The hard part is deciding how old a copied value is allowed to be.',
    'Product 42 costs ₹500. Assume a 60-second cache TTL, a 5 ms cache-hit path, and a 50 ms total miss path for this illustrative calculation.',
    ['Customer', 'Application', 'Database', 'Cache'], [
      step('Start with a cold miss', 'The customer requests product 42. The app checks product:42 and finds nothing. A miss is normal; it means the app must consult the authoritative store.', 'The cache is an optimization. Correctness must not depend on a key already being present.', ['Request product 42', 'Check product:42', 'Price: ₹500', 'Key absent'], [1, 3], 'The first request cannot use the fast path.'),
      step('Load and fill', 'The app reads ₹500 from the database, stores it in the cache with a 60-second expiry, and returns the product.', 'The app coordinates both operations. Only requested data gets cached, which avoids preloading the entire catalog.', ['Receives ₹500', 'Read + cache + reply', 'Price: ₹500', '₹500; TTL 60 s'], [1, 2], 'This miss takes the assumed 50 ms path.'),
      step('Serve a warm hit', 'The next request finds the cached product. At a measured 90% hit rate, mean latency in this simplified model is 0.9 × 5 + 0.1 × 50 = 9.5 ms.', 'The weighted mean describes this workload, not p99 latency. Misses and queueing can still dominate the slowest requests.', ['Receives ₹500', 'Skip database read', 'No read this time', 'Hit: ₹500'], [3, 1], 'A hit uses the assumed 5 ms path.'),
      step('Update the source and invalidate', 'A seller changes the price to ₹550. After the database commit, the app deletes product:42 so the next reader refills from the new value.', 'Deleting after commit reduces stale reads, but concurrent reads can refill an old value. Stronger freshness needs versioning or coordination, not just a TTL.', ['Next read: cache miss', 'Invalidate after write', 'Price: ₹550', 'Key deleted'], [1, 3], 'The next uncontended read reloads ₹550.'),
    ], 'A high hit rate lowers load, but outages and synchronized expiry can flood the source. Bound fallback concurrency and consider coalescing requests for the same key.',
    'Does a 60-second TTL prove every price is at most 60 seconds old?', 'Not without assumptions. A stale in-flight read can refill the cache after a write, and a lagging source can return old data. TTL limits the lifetime of a cache entry; it is not a complete freshness guarantee.'),
  databases: study(
    'Transfer money as one transaction',
    'A transaction groups changes into one unit with defined isolation and durability guarantees. Atomicity makes all included changes commit or none; isolation determines how concurrent transactions interact.',
    'Account A has ₹1,000 and B has ₹200. Transfer ₹300, preserving a total of ₹1,200. All changes are in one database transaction.',
    ['Transfer request', 'Transaction', 'Account A', 'Account B'], [
      step('Begin and check the balance', 'Start a transaction and protect the relevant account records using a suitable locking or isolation strategy. Validate that A can fund the transfer.', 'A plain read followed by an unprotected write can race with another transfer. “Inside a transaction” does not automatically choose the right isolation.', ['Transfer ₹300', 'Active transaction', '₹1,000', '₹200'], [1, 2], 'The business rule is checked against coordinated state.'),
      step('Debit within the transaction', 'Subtract ₹300 from A inside the transaction. The operation is still uncommitted; it is not yet a completed transfer.', 'A partial debit must not become the durable outcome if the credit fails. Keep both changes in the same atomic unit.', ['Waiting', 'Debit pending', '₹700 pending', '₹200'], [1, 2], 'The transaction has an intermediate state.'),
      step('Credit and commit', 'Add ₹300 to B and commit the transaction. Only report transfer success after commit has succeeded under the database’s configured durability guarantees.', 'The full invariant now holds: ₹700 + ₹500 = ₹1,200. If the transaction aborts before commit, both changes roll back.', ['Success after commit', 'Committed', '₹700 committed', '₹500 committed'], [1, 3], 'The transfer preserves the total balance.'),
      step('Handle an uncertain response', 'If the connection drops after commit, retry using a unique transfer ID and return the existing outcome rather than executing a second debit.', 'Database atomicity does not deduplicate separate application requests. Request identity and transactional correctness solve different problems.', ['Retry same transfer ID', 'Return stored result', 'Still ₹700', 'Still ₹500'], [0, 1], 'A retry does not transfer another ₹300.'),
    ], 'Stronger isolation simplifies some reasoning but can increase waiting or aborts. Design bounded retries for deadlocks and serialization failures.',
    'Can one local transaction atomically update accounts in unrelated databases?', 'Not by itself. Cross-database work requires a supported distributed transaction protocol or a workflow with explicitly defined intermediate states and compensation.'),
  'database-scaling-techniques': study(
    'Scale reads without hiding replica lag',
    'An index speeds selected access patterns, replicas copy data to more machines, and shards divide data across machines. These techniques solve different bottlenecks and have different correctness costs.',
    'A profile service sends writes to a primary and ordinary reads to a replica. Assume asynchronous replication and a recent address update from version 7 to 8.',
    ['User', 'API router', 'Primary', 'Read replica'], [
      step('Write to the primary', 'The user updates an address. The primary commits version 8 and returns success to the API. The replica still holds version 7.', 'Asynchronous replication allows the primary to acknowledge without waiting for every reader to catch up.', ['Saved address v8', 'Write complete', 'Version 8', 'Version 7'], [1, 2], 'Write success does not imply every replica is current.'),
      step('Read from a lagging copy', 'A refresh is routed to the replica and returns version 7. The user appears to have lost the update even though it is durable on the primary.', 'A read replica increases read capacity but can weaken the read-after-write experience.', ['Sees old address', 'Read from replica', 'Version 8', 'Returns version 7'], [3, 1], 'The application observes a stale read.'),
      step('Choose an explicit consistency policy', 'Route this user’s immediate confirmation read to the primary, or wait until a replica has applied the required version before using it.', 'Blindly waiting a fixed time is only a heuristic. A version-aware barrier or primary read gives a clearer guarantee.', ['Sees version 8', 'Read primary', 'Returns version 8', 'Still catching up'], [2, 1], 'Freshness-sensitive reads use a different route.'),
      step('Apply the replicated update', 'The replica applies version 8. Ordinary reads can now return the new address from either copy; future writes can create lag again.', 'Replication lag is a changing condition. Monitor it and define how routing behaves when a replica falls far behind.', ['Consistent view now', 'Normal read routing', 'Version 8', 'Version 8'], [2, 3], 'Replication distributes reads, not independent write ownership.'),
    ], 'Primary reads improve freshness but add load to the writer. Sharding can distribute writes but complicates cross-shard operations.',
    'Will adding replicas automatically make an unindexed query efficient?', 'No. Replicas spread read load, but each may still perform the same expensive scan. Improve the access path and verify the query plan as well.'),
  'storage-systems': study(
    'Upload a large video without proxying every byte',
    'Object storage manages blobs by key; a metadata database manages searchable records and workflow state. Keeping these responsibilities separate makes large-file handling easier to scale.',
    'A user uploads a 200 MB video. The API stores the title and ownership, while an object store holds the video bytes.',
    ['Uploader', 'Metadata API', 'Object store', 'Media worker'], [
      step('Create an upload intent', 'The API authenticates the user, chooses an object key, creates a pending metadata record, and issues short-lived, scoped upload permission.', 'The server must control the destination and allowed operation. A client-provided filename is not a trustworthy authorization boundary.', ['Request upload', 'Status: pending', 'No object yet', 'Waiting'], [0, 1], 'A pending record represents an upload that may still fail.'),
      step('Transfer the bytes', 'The browser uploads directly to the object store using the scoped permission. Multipart upload can retry individual parts of a large file.', 'This removes the API server from the bulk data path. It does not remove the need to validate size, type, ownership, and integrity.', ['Send 200 MB', 'No byte proxying', 'Object uploaded', 'Waiting'], [0, 2], 'The blob exists separately from the metadata row.'),
      step('Verify and process', 'After verifying the completed object, schedule media processing. The worker produces thumbnails or variants and records the result.', 'An upload notification can be repeated or delayed. Make job scheduling and processing idempotent and verify the actual object.', ['Upload complete', 'Status: processing', 'Original stored', 'Build variants'], [2, 3], 'An uploaded file is not necessarily ready for playback.'),
      step('Publish the ready state', 'Only after required outputs exist does the workflow mark the video ready. Readers receive authorized delivery URLs; abandoned uploads are cleaned up later.', 'A database transaction cannot normally atomically commit an object-store upload. Explicit states and reconciliation handle partial completion.', ['Can play video', 'Status: ready', 'Original + variants', 'Complete'], [3, 1], 'Metadata now accurately describes usable media.'),
    ], 'Direct upload reduces API bandwidth but adds scoped permissions, orphan cleanup, and a multi-step readiness workflow.',
    'What if the browser closes after uploading bytes but before updating metadata?', 'The object may exist while the record stays pending. Use verified completion events or reconciliation to finish the workflow, and expire abandoned objects according to policy.'),
  tradeoffs: study(
    'Choose freshness separately for catalog and checkout',
    'A trade-off is a choice between valuable properties under a specific constraint. Different operations in the same product can need different consistency, latency, and availability guarantees.',
    'A shop has one item left. Product browsing can tolerate a briefly stale stock label, but checkout must not sell the same unit twice.',
    ['Shopper', 'Catalog cache', 'Checkout', 'Inventory database'], [
      step('Read a fast catalog copy', 'The product page reads a cached “1 in stock” label. This helps browsing stay responsive even when the inventory database is busy.', 'A display hint can tolerate some staleness when the product contract makes clear that checkout confirms availability.', ['Browsing', 'Shows 1 in stock', 'Not started', 'Available: 1'], [0, 1], 'Fast browsing uses a copied value.'),
      step('Reserve at the authority', 'Checkout conditionally reserves the item in the inventory database. Only one concurrent buyer can change available stock from 1 to 0.', 'The cached count is not authoritative enough to approve a purchase. Coordination belongs at the reservation boundary.', ['Buy item', 'May still show 1', 'Reserve if available', 'Available: 0'], [2, 3], 'The last unit has one successful reservation.'),
      step('Lose access to inventory', 'A network partition prevents another checkout from reaching inventory. This design refuses to confirm a new reservation while it cannot establish stock.', 'For this operation, preserving the no-oversell rule means accepting failed or delayed requests during the partition.', ['Checkout unavailable', 'Browsing still works', 'Cannot confirm stock', 'Unreachable'], [2, 3], 'The browsing and purchasing experiences degrade differently.'),
      step('Recover and reconcile', 'Connectivity returns, inventory remains at 0, and the catalog cache is refreshed or invalidated. A new checkout correctly reports sold out.', 'Availability is not one universal switch for the whole application. Document the behavior of each operation during failure.', ['Sees sold out', 'Shows 0 in stock', 'Reject unavailable item', 'Available: 0'], [3, 1], 'Freshness catches up without approving a duplicate sale.'),
    ], 'Strict reservation rules can reduce checkout availability during a partition. Allowing offline purchases would require an explicit oversell or preallocated-stock policy.',
    'Does a stale stock label prove the reservation system is incorrect?', 'No. The correctness rule applies to committed reservations. A stale display is a user-experience issue; an oversold reservation violates the inventory invariant.'),
  'architectural-patterns': study(
    'Separate a slow capability when it earns its cost',
    'A monolith deploys capabilities together; services create separate deployment and failure boundaries. A useful boundary follows ownership and workload, not simply the number of classes in the codebase.',
    'A shop starts as one application. Image resizing consumes most CPU during uploads, while checkout needs predictable response times.',
    ['Shopper', 'Shop application', 'Image jobs', 'Image worker'], [
      step('Keep the first design simple', 'Catalog, checkout, and uploads initially share an application. Internal modules can still have clear interfaces and ownership.', 'A single deployment does not require tangled code. Start with boundaries in code before adding network boundaries.', ['Browse + buy', 'One deployment', 'No queue yet', 'Inline resizing'], [0, 1], 'The initial operating model is straightforward.'),
      step('Measure interference', 'A burst of uploads runs expensive resizing in the request-serving process. Checkout latency rises because both paths compete for CPU.', 'The reason to extract a capability is observable interference or an independent requirement, not a rule that every feature needs a service.', ['Slow checkout', 'CPU saturated', 'Upload burst', 'Shares API CPU'], [1, 3], 'A specific workload is hurting an important objective.'),
      step('Introduce an asynchronous boundary', 'The application stores upload metadata and enqueues resizing work. Dedicated workers consume jobs and publish completion status.', 'Uploads now need a processing state, but checkout no longer waits for image work to complete.', ['Checkout responsive', 'Accept upload intent', 'Pending image tasks', 'Independent process'], [2, 3], 'The expensive workload moves out of the request path.'),
      step('Scale the expensive part', 'Add image workers according to queue age and processing capacity. Keep ordering, deduplication, and failure reporting in the job contract.', 'Independent scaling is useful, but deployment, tracing, retries, and compatibility now span multiple processes.', ['Images appear later', 'Track job status', 'Backlog decreases', 'More worker capacity'], [3, 1], 'One justified boundary changes the scaling model.'),
    ], 'Service extraction isolates resource use but introduces distributed failure modes and asynchronous user experiences.',
    'Should every internal module immediately become a separate service?', 'No. Extract when independent scaling, ownership, reliability, or deployment requirements justify the coordination cost. Module boundaries remain valuable inside one deployment.'),
  'microservices-patterns': study(
    'Stop a failing dependency from exhausting checkout',
    'A circuit breaker remembers recent dependency failures and temporarily stops calls that are likely to fail. It is different from a timeout: a timeout bounds one call, while a breaker changes subsequent admission.',
    'Checkout calls an optional recommendations service. Assume a breaker configured to open after 3 consecutive failures and allow one probe after a cooldown.',
    ['Checkout', 'Circuit breaker', 'Recommendations', 'Fallback response'], [
      step('Allow normal calls', 'The breaker is closed, so calls reach recommendations. Each call still has a timeout and a bounded concurrency budget.', 'A closed breaker does not prevent a slow dependency from consuming resources. Timeouts and bulkheads complement it.', ['Request suggestions', 'Closed', 'Healthy', 'Unused'], [1, 2], 'The normal response includes suggestions.'),
      step('Observe repeated failures', 'Three consecutive calls time out under this example policy. The breaker records the failures and opens.', 'A production policy should account for traffic volume and noisy failures. A tiny sample can otherwise trigger needless state changes.', ['Calls timing out', 'Open after 3 failures', 'Unavailable', 'Ready'], [0, 1], 'The breaker stops admitting ordinary dependency calls.'),
      step('Fail fast with a safe fallback', 'New checkouts skip recommendations and return an empty suggestions list. They still execute the required payment and inventory checks.', 'A fallback must preserve the business contract. It is safe to omit optional recommendations; it is not safe to invent successful payment results.', ['Checkout continues', 'Open: skip call', 'No new calls', 'Empty suggestions'], [1, 3], 'Optional failure no longer consumes the full timeout per request.'),
      step('Probe before reopening traffic', 'After cooldown, admit one test request in half-open state. If it succeeds, close the breaker; if it fails, reopen and wait again.', 'Releasing the entire backlog at once can overwhelm a recovering service. Controlled probes test recovery with limited load.', ['Probe request', 'Half-open → closed', 'Probe succeeds', 'No longer needed'], [1, 2], 'Normal traffic resumes after a successful recovery check.'),
    ], 'Fail-fast behavior protects resources but can hide a recovered dependency until the next probe. Tune thresholds to the actual failure and recovery patterns.',
    'Can checkout pretend a failed payment succeeded as its fallback?', 'No. A fallback cannot violate the business invariant. Required operations need an honest pending or failed state, while optional features can degrade safely.'),
  'distributed-systems-fundamentals': study(
    'Understand a timeout without guessing the outcome',
    'Across a network, a caller cannot directly observe the other machine’s state. A missing response may mean a lost request, slow processing, a crash, or a lost reply after success.',
    'A client submits payment operation pay-42. The payment service commits the operation, but the response path is interrupted.',
    ['Client', 'Network', 'Payment service', 'Payment ledger'], [
      step('Send one operation', 'The client assigns pay-42 and sends the payment request with a bounded timeout. The network delivers it to the service.', 'A timeout is a waiting budget. It is not a command that can reliably undo work on a remote machine.', ['Send pay-42', 'Request delivered', 'Process pay-42', 'No entry yet'], [0, 2], 'The service may continue after the client stops waiting.'),
      step('Commit the payment', 'The service atomically records the operation and its result in the ledger. The durable status for pay-42 is now succeeded.', 'A durable operation identifier lets retries and status lookups refer to the same business action.', ['Still waiting', 'Response pending', 'Committed', 'pay-42 succeeded'], [2, 3], 'The payment has happened.'),
      step('Lose the response', 'The reply does not reach the client before its timeout. The client must show an unresolved outcome or check status rather than claiming the payment did not happen.', 'Failure detection is imperfect. “I did not hear back” provides less information than “the operation was rejected”.', ['Outcome unknown', 'Reply lost', 'Already succeeded', 'pay-42 succeeded'], [2, 1], 'Caller knowledge and server state differ.'),
      step('Resolve by identity', 'The client queries pay-42 or retries with the same key. The service returns the saved success without charging again.', 'Blind retries with new identifiers turn a transient communication failure into duplicated business work.', ['Success confirmed', 'Connectivity restored', 'Return recorded result', 'One payment'], [3, 2], 'Recovery discovers the original outcome.'),
    ], 'Retries improve resilience only when bounded, delayed, and safe. Uncoordinated retries can amplify an overloaded dependency.',
    'Does a timeout prove the payment service crashed?', 'No. It only proves no acceptable response arrived within the waiting budget. The service may be healthy and the payment may already have committed.'),
  'time-and-ordering': study(
    'Track causality without trusting wall clocks',
    'A logical clock orders events according to observed communication. A Lamport clock increases for each local event; on receive it advances to one more than the maximum of the local and received timestamps.',
    'Service A has logical clock 4 and service B has clock 9. We want the receive event to sort after the message that caused it.',
    ['Service A', 'Message A → B', 'Service B', 'Event log'], [
      step('Timestamp the send', 'A increments its clock from 4 to 5 and attaches timestamp 5 to a message. This number is a logical counter, not seconds.', 'Wall clocks can drift or jump. Logical timestamps capture ordering constraints without pretending to measure elapsed time.', ['Clock: 5', 'Timestamp: 5', 'Clock: 9', 'Send at 5'], [0, 1], 'The send event has timestamp 5.'),
      step('Advance at the receiver', 'B receives timestamp 5 and sets its clock to max(9, 5) + 1 = 10 before recording the receive event.', 'Taking only received + 1 would move B backward to 6. Taking the maximum preserves B’s existing event order.', ['Clock: 5', 'Delivered', 'Clock: 10', 'Receive at 10'], [1, 2], 'The receive timestamp exceeds the send timestamp.'),
      step('Record a local event', 'B performs another local event and increments to 11. The event log can order B’s receive at 10 before this event at 11.', 'Logical ordering helps reconstruct a valid causal sequence, but the difference of 1 does not mean one millisecond elapsed.', ['Clock: 5', 'Delivered', 'Clock: 11', 'B events: 10, 11'], [2, 3], 'Clock differences are not durations.'),
      step('Recognize the limit', 'An independent service can produce timestamp 8 without ever communicating with B. Comparing 8 and 10 alone does not prove those events caused each other.', 'If event X causes Y, its Lamport timestamp is smaller. The reverse implication is false; vector clocks can represent more information about concurrency.', ['Independent activity', 'No new message', 'Clock: 11', 'Order ≠ proof of cause'], [0, 3], 'A total ordering can include events that are actually concurrent.'),
    ], 'Scalar clocks are compact but lose concurrency information. Vector clocks carry more causal detail at the cost of metadata and membership complexity.',
    'Can you compute network latency by subtracting Lamport timestamps?', 'No. They count logical progress, not elapsed physical time. Measure durations with suitable clocks and account for clock synchronization when comparing different machines.'),
  'consensus-and-coordination': study(
    'Commit an entry with a majority',
    'Consensus lets replicas agree on an ordered history despite some failures. A leader-based protocol coordinates proposals, while terms, log checks, and quorum rules prevent conflicting committed histories.',
    'Use a three-node Raft-style cluster. A is leader in the current term; B and C are followers. This example proposes a new entry in that same term.',
    ['Client', 'Leader A', 'Follower B', 'Follower C'], [
      step('Append a proposal', 'The client asks to reserve seat A7. The leader appends the new current-term entry to its log and starts replication.', 'Being present on the leader is not yet the same as being committed. A lone leader can fail before another replica receives the entry.', ['Reserve A7', 'Entry pending', 'No entry yet', 'No entry yet'], [0, 1], 'One of three replicas has the proposal.'),
      step('Reach a majority', 'B accepts the entry after the protocol’s log checks and acknowledges. A plus B form a majority of two out of three, allowing this current-term entry to commit.', 'Majorities intersect, but quorum counting alone is not the whole protocol. Election and log-matching rules preserve the committed history.', ['Waiting', 'Entry committed', 'Entry replicated', 'Temporarily offline'], [1, 2], 'The cluster can tolerate one unavailable replica for this write.'),
      step('Apply and respond', 'The leader applies the committed operation to its state machine and returns success. C can receive the missing log entry when it reconnects.', 'Clients should receive successful commitment only after the protocol’s conditions are met, not merely after a local append.', ['Reservation succeeded', 'Applied + responded', 'Commit notified', 'Will catch up'], [1, 0], 'The acknowledged operation belongs to the committed history.'),
      step('Lose the majority', 'Now both followers are unreachable. A may receive another proposal but cannot commit it alone. The service times out or rejects the write.', 'Refusing progress without a quorum protects agreement. Three replicas cannot continue committing with only one reachable member.', ['New write unavailable', 'Cannot commit alone', 'Unreachable', 'Unreachable'], [0, 1], 'Replication count and reachable quorum are different.'),
    ], 'Quorum coordination favors a consistent history over write availability when too many members are unreachable. Replication also adds communication latency.',
    'How many failures can five voting nodes tolerate while retaining a majority?', 'A majority is three, so two nodes may be unavailable if the remaining three can communicate. Safety still depends on the consensus protocol, not just the count.'),
  'distributed-transactions': study(
    'Recover a checkout with a saga',
    'A saga is a sequence of local transactions with explicit recovery actions. It does not make all services commit at the same instant; intermediate states are visible and compensating actions can themselves fail.',
    'Checkout reserves stock, authorizes payment, then confirms an order. Inventory and payment belong to different services.',
    ['Order workflow', 'Inventory', 'Payment', 'Recovery queue'], [
      step('Reserve inventory', 'Create order 81 in pending state and request a temporary reservation. Inventory commits reservation R81 in its own database.', 'The workflow must record progress durably so a restarted coordinator can resume without reserving the same stock again.', ['Order 81 pending', 'R81 reserved', 'Not attempted', 'Empty'], [0, 1], 'Stock is held, but the order is not confirmed.'),
      step('Attempt payment', 'Send an authorization request with a stable operation key. In this example the provider returns a definite decline, not an ambiguous timeout.', 'A known decline can trigger compensation. An unknown payment outcome should be resolved before assuming nothing happened.', ['Payment declined', 'R81 still held', 'Definite decline', 'Release needed'], [0, 2], 'The workflow cannot proceed to confirmation.'),
      step('Schedule compensation', 'Durably record a release-R81 recovery task and mark the order as cancelling. If inventory is temporarily down, retain and retry the task.', 'Compensation is a new business action, not a magical rollback of every remote side effect.', ['Cancelling', 'Temporarily unreachable', 'No authorization', 'release-R81 pending'], [0, 3], 'Recovery remains visible and retryable.'),
      step('Finish recovery', 'Inventory comes back, applies the idempotent release, and confirms it. The workflow marks order 81 cancelled.', 'An already released reservation must tolerate another release attempt. Monitor stuck workflows and define a manual recovery path.', ['Order cancelled', 'R81 released', 'No authorization', 'Task complete'], [3, 1], 'Inventory is available again and the workflow is terminal.'),
    ], 'Sagas avoid holding one distributed transaction open, but require explicit intermediate states, compensation, and reconciliation.',
    'What if payment times out instead of returning a definite decline?', 'Keep the outcome unresolved and query or retry using the same operation key. Releasing inventory and retrying a fresh payment without reconciliation can produce a paid order with no reservation.'),
  'data-structures-for-scale': study(
    'Skip unnecessary reads with a Bloom filter',
    'A Bloom filter is a compact membership summary. In a correctly maintained standard filter, “absent” is definitive, while “maybe present” requires checking the authoritative store. It saves work when many lookups miss.',
    'A service checks whether a username exists. For a small illustration use 8 bits and 2 hash positions per username; this tiny filter is deliberately collision-prone.',
    ['Lookup request', 'Hash functions', 'Bloom bits', 'User database'], [
      step('Insert an existing username', 'Suppose the two hashes of maya map to positions 1 and 5. Set those bits and keep the real username in the database.', 'Bits summarize membership; they do not store the original value. Many distinct usernames can share positions.', ['Insert maya', 'Positions 1, 5', 'Set {1, 5}', 'Contains maya'], [1, 2], 'The filter records a compact summary of maya.'),
      step('Reject a definite miss', 'Suppose leo maps to positions 2 and 5. Position 2 is unset, so leo is definitely absent from the represented set.', 'Every inserted item sets all its positions. One missing bit proves the item was not inserted, provided the filter is complete and maintained correctly.', ['Check leo', 'Positions 2, 5', 'Bit 2 = 0', 'Read skipped'], [2, 0], 'An unnecessary database lookup is avoided.'),
      step('Observe a false positive', 'Suppose nia maps to positions 1 and 5 too. Both bits are set, so the filter says “maybe”, even though nia was never inserted.', 'Hash collisions mean a positive answer is not proof of membership. A filter cannot replace the database or a uniqueness constraint.', ['Check nia', 'Positions 1, 5', 'Both bits = 1', 'Must verify'], [2, 3], 'The database still decides whether nia exists.'),
      step('Verify against the source', 'The database returns absent for nia. More bits or a better-sized filter would reduce false positives, but never turn “maybe” into proof.', 'Choose memory and hash count for expected set size and acceptable false-positive rate. A stale filter can break the no-false-negative assumption.', ['nia is available', 'Collision understood', 'Summary unchanged', 'nia not found'], [3, 0], 'Correctness comes from authoritative verification.'),
    ], 'The filter saves reads at the cost of memory, hash work, and maintaining a complete summary. Standard Bloom filters cannot safely delete by clearing shared bits.',
    'Can you clear bits 1 and 5 when removing maya?', 'Not in a standard Bloom filter: other inserted usernames may depend on the same bits. Use a suitable deletion-capable structure or rebuild the filter.'),
  'big-data-processing': study(
    'Count orders when events arrive late',
    'Batch processing works on a bounded collection; streaming maintains results as events arrive. Event time describes when something happened, while processing time describes when a system handled its record.',
    'Count orders in the event-time window 12:00–12:01. Order O3 happened at 12:00:50 but arrives after 12:01 because of a network delay.',
    ['Order events', 'Stream processor', 'Window state', 'Dashboard'], [
      step('Collect by event time', 'O1 at 12:00:10 and O2 at 12:00:40 arrive promptly. The processor assigns both to the 12:00–12:01 window.', 'Grouping by arrival time would mix delayed records into a later minute, changing the question the metric answers.', ['O1 + O2 received', 'Use event timestamps', 'Count: 2', 'Provisional: 2'], [1, 2], 'The current answer is two orders in that event-time minute.'),
      step('Publish a provisional result', 'The wall clock passes 12:01. The dashboard may show 2 while the system still allows a configured lateness interval for this window.', 'A closed wall-clock minute does not prove all its events have arrived. Faster results often need later correction.', ['O3 still delayed', 'Window still amendable', 'Count: 2', 'Provisional: 2'], [2, 3], 'Low-latency results are explicitly provisional.'),
      step('Apply the late event', 'O3 arrives within the allowed lateness policy. Its event timestamp is 12:00:50, so the processor updates the earlier window to 3.', 'Store event IDs or use a suitable deduplication policy so a replay of O3 does not increment the count again.', ['O3 received late', 'Assign to prior window', 'Count: 3', 'Corrected: 3'], [0, 1], 'The late event corrects the minute it belongs to.'),
      step('Finalize under a policy', 'When the watermark and allowed-lateness policy expire the window, release its working state. Send later arrivals to a correction or reconciliation path.', 'A watermark is an estimate of event-time progress, not proof that an extremely delayed event cannot appear.', ['Very late → correction', 'Window state expires', 'Finalized under policy', 'Published count: 3'], [2, 3], 'The system makes its completeness-versus-latency policy visible.'),
    ], 'Longer lateness allowances improve completeness but retain more state and delay final results. Batch reconciliation can repair very late data.',
    'Why should replayed events carry stable IDs?', 'A processor may receive an event again after recovery. A stable identity lets the counting policy distinguish a replay from a new order.'),
  'deployment-patterns': study(
    'Release a new version with a small canary',
    'A deployment changes running software; a release changes user-visible behavior. Progressive delivery exposes a small population first, compares meaningful signals, and keeps a compatible recovery path.',
    'Version 2 changes checkout pricing. Begin with 5% of traffic on v2 and 95% on v1; assume comparable request mixes for this teaching example.',
    ['Traffic router', 'Version 1', 'Version 2', 'Release metrics'], [
      step('Keep the old version serving', 'Deploy v2 alongside v1 and verify readiness before assigning public traffic. Database changes must support both versions during overlap.', 'Starting a process is not the same as being ready. A destructive schema change can make rollback impossible before traffic even moves.', ['100% to v1', 'Serving', 'Ready, no traffic', 'Baseline recorded'], [0, 1], 'The current version remains the baseline.'),
      step('Expose a small sample', 'Route 5% to v2. Use stable assignment if users must not switch versions mid-flow, and avoid biasing the sample toward only easy requests.', 'A small percentage limits exposure, but it needs enough representative traffic to produce useful evidence.', ['95% v1 / 5% v2', 'Baseline traffic', 'Canary traffic', 'Compare cohorts'], [0, 2], 'The canary is a measured experiment.'),
      step('Detect a regression', 'Suppose v1 has 1% checkout errors and v2 has 8% with sufficient samples. Pause expansion and investigate the difference.', 'A fleet-wide average can hide a severe problem in a small canary. Compare version-specific errors, latency, and business outcomes.', ['Hold at 5%', 'Errors: 1%', 'Errors: 8%', 'Regression detected'], [2, 3], 'The evidence argues against increasing exposure.'),
      step('Route back and verify', 'Send new traffic to v1, drain v2 safely, and confirm error rates recover. Reconcile any incorrect side effects created during the canary.', 'Rolling back code does not undo data already written or payments already attempted. Recovery includes data and business effects.', ['100% to v1', 'Serving all new traffic', 'Draining', 'Verify recovery'], [0, 1], 'The rollout stops at a bounded exposure.'),
    ], 'Canaries reduce blast radius but add parallel infrastructure, routing, compatibility, and observation requirements.',
    'Is a canary healthy just because CPU is low?', 'No. It may return incorrect prices or fail checkout quickly. Include user-visible correctness and business signals, not only host utilization.'),
  observability: study(
    'Explain a slow checkout with metrics, traces, and logs',
    'Metrics reveal aggregate behavior, traces follow work across boundaries, and logs record detailed events. Together they help distinguish a symptom from its cause.',
    'Checkout p95 latency rises from 200 ms to 900 ms. A trace for a slow request includes API, inventory, and payment spans.',
    ['Latency metric', 'Request trace', 'Payment span', 'Structured logs'], [
      step('Detect the user-visible change', 'A latency metric shows that 95% of requests finish within 900 ms instead of 200 ms over the chosen measurement window.', 'p95 is not the average and does not say every request took 900 ms. Combine it with traffic, error rate, and sample counts.', ['p95: 900 ms', 'Find slow samples', 'Not inspected', 'Not inspected'], [0, 1], 'The metric identifies a symptom worth investigating.'),
      step('Locate the time', 'Inspect representative traces. In one 920 ms request, the payment span occupies 760 ms while inventory is fast.', 'Spans can overlap, so adding every duration may exceed total request time. Inspect the critical path and queueing intervals.', ['Regression confirmed', 'Total: 920 ms', 'Payment: 760 ms', 'Search by trace ID'], [1, 2], 'The trace narrows the investigation to a dependency path.'),
      step('Find the detailed event', 'Use the trace ID in structured logs. The payment client reports retries after connection-pool acquisition timeouts.', 'Correlated identifiers connect evidence. Avoid putting personal data or secrets into logs, and keep metric label cardinality bounded.', ['Latency + retries up', 'Trace ID: t42', 'Pool wait + retries', 'Pool acquisition timeout'], [2, 3], 'The detailed event suggests a testable cause.'),
      step('Verify a recovery', 'Bound retries and investigate pool saturation or downstream slowness. After a controlled fix, compare latency, error rate, throughput, and saturation under similar traffic.', 'Correlation is a lead, not a final diagnosis. A recovery claim should survive comparison with the original symptom and workload.', ['p95 recovers', 'Shorter critical path', 'Pool wait reduced', 'Fewer retry events'], [3, 0], 'The fix is evaluated against user impact.'),
    ], 'More telemetry increases visibility but costs storage and processing. Sample traces carefully and retain enough error detail to investigate failures.',
    'Can one fast trace disprove a p95 regression?', 'No. A single trace is one sample; p95 describes a distribution. Inspect representative slow traces and verify that sampling has not excluded important failures.'),
  'advanced-security': study(
    'Rotate a credential without interrupting the service',
    'Security includes limiting authority, protecting secrets, and recovering when credentials change or leak. Rotation is a workflow: introduce, distribute, verify, then revoke.',
    'An API uses credential A to access a database. The database supports an overlap period with both A and B valid, and the application can refresh its credentials.',
    ['Secret store', 'API instances', 'Database', 'Audit monitor'], [
      step('Create a narrowly scoped replacement', 'Create credential B with only the permissions the API requires. Store it in a secret-management system rather than source code or logs.', 'Rotation cannot compensate for excessive privilege. A stolen read-only credential and a stolen administrator credential have different impact.', ['A + B stored', 'Using A', 'Accepts A + B', 'Creation recorded'], [0, 2], 'The replacement is ready while the old credential still works.'),
      step('Refresh running instances', 'Roll or reload API instances so new connections use B. Existing connection pools may continue using A until they are drained or refreshed.', 'Changing the secret value does not prove every process has reloaded it. Track versions across all instances and background jobs.', ['Current version: B', 'Migrate to B', 'Accepts A + B', 'Track instance versions'], [0, 1], 'The fleet moves through a controlled overlap period.'),
      step('Verify real access', 'Run a harmless authorized operation through each updated path and inspect authentication failures. Confirm required workers and scheduled jobs also use B.', 'A successful secret fetch does not prove the database accepts the new credential or that its permissions are sufficient.', ['B distributed', 'Use B successfully', 'B access verified', 'No stale users found'], [1, 2], 'Application behavior confirms the new credential works.'),
      step('Revoke and watch', 'Revoke A after verified migration, drain old authenticated sessions if the database requires it, and monitor for failures or unexpected use.', 'Revocation semantics vary: invalidating a credential may not terminate existing sessions. Include active connections in the recovery plan.', ['A retired', 'Using B', 'A revoked', 'Watch failures + misuse'], [2, 3], 'The old credential is no longer a valid new access path.'),
    ], 'Overlap enables gradual rollout but temporarily leaves two credentials valid. Emergency compromise may require faster revocation with a deliberate availability trade-off.',
    'Does deleting a leaked secret from the repository make it safe again?', 'No. Copies may remain in history, caches, logs, or someone else’s machine. Revoke or rotate the credential, investigate use, and remove the exposed material.'),
};

export function getSystemDesignWalkthrough(sectionSlug) {
  return systemDesignWalkthroughs[sectionSlug] || null;
}
